head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS10301.xml";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 발행기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_OrgStdCd);
    var dsNm = 'BNS_STRIP_STAT';
    var qryId = 'lds.stf.bnschg.select.listStripStatDtl';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_OrgStdCd, arrPar[0].STD_CD);
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDtlAndMktactDtl
 * 설명       : 시장조치상세내역 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDtlAndMktactDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), 'STD_CD'),
        STRT_DD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    //호출파라미터설정
    scwin.fn_SetParam();
    //목록조회
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_스트립분리내역.xls";
    $c.data.downloadGridViewExcel(grd_List, "스트립분리내역", "", 8);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount > 0) {
        $c.stf.setObjectValue(txb_OrgIsuNm, dts_List.getCellData(1, 'ORG_ISU_NM'));
        $c.stf.setObjectValue(txb_OrgStdCd, dts_List.getCellData(1, 'ORG_STD_CD'));
        $c.stf.setObjectValue(edt_OrgIsuDd, dts_List.getCellData(1, 'ORG_ISU_DD'));
        $c.stf.setObjectValue(edt_OrgListDd, dts_List.getCellData(1, 'ORG_LIST_DD'));
        $c.stf.setObjectValue(edt_OrgRedmptDd, dts_List.getCellData(1, 'ORG_REDMPT_DD'));
        $c.stf.setObjectValue(edt_OrgCoupnRt, dts_List.getCellData(1, 'ORG_COUPN_RT'));
        $c.stf.setObjectValue(edt_OrgListAmt, dts_List.getCellData(1, 'ORG_LIST_AMT'));
        $c.stf.setObjectValue(edt_OrgStripNsprtBal, dts_List.getCellData(1, 'ORG_STRIP_NSPRT_BAL'));
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    if (colid == 'ISU_NM') {
        scwin.fn_GetPar = fn_GetParIsuDtlAndMktactDtl;
        $c.bns.fn_PopIsuDtlAndMktactDtl(pnl_Search);
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
